-- Canonical credential taxonomy registry.
--
-- Mirrors the in-code registry (apps/api/app/skilled_pro/taxonomy.py — the
-- source of truth; seed block below is generated by
-- scripts/gen_credential_definitions_sql.py). All additive:
--   • credential_definitions gains job_families / validity_note / verification_url
--   • jobs gains required_credentials_canonical (normalizer output, additive —
--     raw required_credentials is never overwritten)
--   • ~127 canonical definitions upserted, covering all 44 job families

BEGIN;

ALTER TABLE public.credential_definitions
  ADD COLUMN IF NOT EXISTS job_families     TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS validity_note    TEXT,
  ADD COLUMN IF NOT EXISTS verification_url TEXT;

-- Job-side canonicalization: [{raw, slug, name, confidence}] per required
-- credential that the normalizer matched confidently. Populated by
-- scripts/backfill_credential_taxonomy.py; consumed by the recompute
-- data-prep layer so both sides of the credential gate meet on canonical names.
ALTER TABLE public.jobs
  ADD COLUMN IF NOT EXISTS required_credentials_canonical JSONB;

CREATE INDEX IF NOT EXISTS idx_credential_defs_families
  ON public.credential_definitions USING gin(job_families);

INSERT INTO public.credential_definitions
